+          author: formData.get("author"),
+          notes: formData.get("notes"),
+        }),
+      });
+      const result = await response.json();
+
+      if (!response.ok) {
+        setError(result.error || "Couldn’t add that book. Please try again.");
+        return;
+      }
+
+      form.reset();
+      router.refresh();
+    } catch {
+      setError("Couldn’t save right now. Please try again.");
+    } finally {
+      setSaving(false);
+    }
+  }
+
