+      setMessage("Couldn’t update. Try again.");
+    } finally {
+      setBusy(false);
+    }
+  }
+
+  async function copyLink() {
+    try {
+      await navigator.clipboard.writeText(window.location.href);
+      setMessage("Link copied");
+      window.setTimeout(() => setMessage(""), 2500);
+    } catch {
+      setMessage("Copying isn’t available here.");
+    }
+  }
+
+  return (
+    <div className={`book-actions${showShare ? " book-actions-detail" : ""}`}>
+      {!finished ? (
+        <button className="finish-button" type="button" onClick={markFinished} disabled={busy}>
+          <span className="finish-icon" aria-hidden="true">✓</span>
+          {busy ? "Saving…" : "Mark finished"}
+        </button>
+      ) : <span className="finished-label"><span aria-hidden="true">✓</span> Finished</span>}
+      {showShare ? <button className="share-button" type="button" onClick={copyLink}>Copy book link <span aria-hidden="true">↗</span></button> : null}
