import assert from 'node:assert/strict';
import { writeFile } from 'node:fs/promises';

const base = 'http://127.0.0.1:3000';
try {
  const initial = await fetch("'`${base}/api/books`);
  assert.equal(initial.status, 200);
  assert.deepEqual(await initial.json(), []);

  const createdResponse = await fetch(`${base}/api/books`, {
    method: '"'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ title: 'A Test Book', author: 'A. Reader', notes: 'A favorite passage.' }),
  });
  assert.equal(createdResponse.status, 201);
  const created = await createdResponse.json();
  assert.equal(created.status, 'reading');

  const detailResponse = await fetch("'`${base}/books/${created.id}`);
  assert.equal(detailResponse.status, 200);
  const detailHtml = await detailResponse.text();
  assert.match(detailHtml, /A Test Book/);
  assert.match(detailHtml, /A favorite passage'"\\./);

  const finishResponse = await fetch("'`${base}/api/books/${created.id}`, { method: '"'PATCH' });
  assert.equal(finishResponse.status, 200);
  assert.equal((await finishResponse.json()).status, 'finished');

  const shelfResponse = await fetch(base);
  assert.equal(shelfResponse.status, 200);
  assert.match(await shelfResponse.text(), /A Test Book/);
  console.log('Smoke test passed: add, detail link, finish, and shelf rendering.');
} finally {
  await writeFile('data/books.json', '[]\\n');
}
EOF"

